"""Write executed intake/recount reports from verified artifacts, not estimated figures."""
import collections
import json
from pathlib import Path
from canada_intake import ROOT,digest

def read(name):return json.loads((ROOT/'reports'/name).read_text(encoding='utf-8-sig'))
def write(name,text):(ROOT/'reports'/name).write_text(text,encoding='utf8')

def run():
    raw=read('CANADA_RAW_INVENTORY.json');rec=read('CANADA_RECONCILIATION.json');assert rec['state']=='PASS';coverage=read('CANADA_SOURCE_COVERAGE.json');versions=read('CANADA_VERSION_LINEAGE.json');quality=read('CANADA_QUALITY_FLAGS.json')
    rows=['# Canada archive forensics — complete read-only intake\n','Completed 2026-11-14, Africa/Cairo (request/source review began13Nov). Originals were opened read-only and re-hashed; no archive was extracted or modified. Both actual deliveries are **JSON arrays, not CSVs**. The intake adapted to the delivered format; it does not pretend to have validated nonexistent CSVs. No Type/vegetation filtering, physical-fire inference, training, adjustment or G4 change.\n',
      '|Request / ZIP|Bytes|SHA-256|\n|---|---:|---|']
    for a in raw['archives']:rows.append(f"|{a['request']} / `{Path(a['path']).name}`|{a['zip_bytes']:,}|`{a['zip_sha256']}`|")
    rows+=['\nActual Windows paths:\n']+[f"- `{a['path']}`" for a in raw['archives']]
    rows+=['\n|Member|Expanded bytes|Raw / accepted / duplicates / excluded|UTC first → last|CRC|\n|---|---:|---|---|---|']
    for a in raw['archives']:
        for m in a['members']:
            if 'rows' in m:rows.append(f"|`{m['name']}`|{m['bytes']:,}|{m['rows']:,} / {m['accepted']:,} / {m['duplicates']:,} / {sum(m['excluded'].values()):,}|{m['first_utc']} → {m['last_utc']}|{m['crc']}|")
    expanded=sum(m['bytes'] for a in raw['archives'] for m in a['members']);total=sum(m['rows'] for a in raw['archives'] for m in a['members'] if 'rows' in m)
    rows+=[f'\nTotal: **{total:,} raw records**, {expanded:,} expanded bytes including README members. Every member was read to CRC-checked EOF; JSON members also have full uncompressed SHA-256 in `CANADA_RAW_INVENTORY.json`. ZIPs have no CSV members. File paths were found on disk, not inferred from processed-request screenshots. Exact delivery URL/email was not supplied; origin is operator-supplied FIRMS request identity with the internal official README link, not an independently signed origin assertion.\n',
      '|Member|Platform|D / N|Literal version counts|Type missing|Geographic W/S/E/N|\n|---|---|---|---|---:|---|']
    for a in raw['archives']:
        for m in a['members']:
            if 'rows' not in m:continue
            cats=m['categories'];rows.append(f"|{m['name']}|{cats['satellite']}|{cats['daynight'].get('D',0):,} / {cats['daynight'].get('N',0):,}|{cats['version']}|{m['missing'].get('type',0):,}|{m['bbox_wsen']}|")
            rows.append(f"\n{m['name']}: distinct UTC instants {m['distinct_acquisition_instants']:,}, distinct dates {m['distinct_dates']:,}; schema key sets {m['schemas']}; exclusions {m['excluded']}; other missing fields {dict((k,v) for k,v in m['missing'].items() if k!='type')}; outside broad Canada envelope {m['outside_broad_canada_envelope']}. Numeric ranges, confidence frequencies, platform/instrument aliases and all member hashes are retained in machine-readable inventory.\n")
    rows+=['\nQuality review flags (retained, not repaired):\n','|'+ '|'.join(quality['columns'])+'|','|'+'|'.join(['---']*len(quality['columns']))+'|']+['|'+'|'.join(str(v) for v in row)+'|' for row in quality['rows']]
    rows+=['\n**Version semantics:** request labels are MODIS C6.1 and S-NPP VIIRS C2. MODIS SP actually contains `6.03` and `61.03`, which are preserved literally; a uniform upstream collection/vintage is not independently established. NRT suffixes and different member date boundaries are explicit, never pooled. VIIRS literal `2` is not evidence of monthly production version2; upstream monthly naming/production chain is absent. NRT Type is absent as a schema distinction, not silently vegetation or zero. Monthly Type defect/reprocessing scope is documented in the support report.\n',
      '**Quality policy:** all valid native confidence classes (including MODIS0 and VIIRS low), finite valid WGS84 coordinates, real UTC date/time, known platform/instrument and D/N; retain zero FRP and every Type. Canonical exact native-field duplicates are removed only within their member. All other exclusions are counted. Country political-border membership, omission/commission error, completeness and cloud-free opportunity are not independently validated. Source coordinates are approximate pixel centers.\n',
      '**Bounded execution:** strict128KiB streaming chunks,64KiB object guard,10000-row batches,24MiB production /18MiB oracle SQLite caches, disk-backed dedup/index and temp sorting. Member expansion guard4GB, total6GB, compression ratio100; safe member names, no execution/extractall. A full-row hash B-tree initially caused random-write bottlenecks; migration to an append store plus compact unique index preserved3,489,777 staged rows in227.06s. The interrupted member was fully re-streamed for counters while committed keys were reused. Final oracle reconciles all identities, preventing silent migration/resume loss. Originals never changed. Initial/resumed logs and `CANADA_INDEX_MIGRATION.json` retain this actual history.\n']
    for filename in ['canada-process-memory.json','canada-resume-memory.json']:
        p=ROOT/'reports'/filename
        if p.exists():
            samples=json.loads(p.read_text(encoding='utf-8-sig'));by=collections.defaultdict(list)
            for s in samples:by[s['pid']].append(s['peak_working_set_bytes'])
            rows.append(f'\nWindows sampled process-peak working sets from `{filename}`: '+', '.join(f'PID{pid}: {max(v):,}B' for pid,v in by.items())+'. Process-local peaks, not combined machine/OS disk cache; sampling can miss the final increment.\n')
    rows.append(f"\nOracle streaming/index elapsed: {read('CANADA_ORACLE_INTAKE.json')['elapsed_s']:.2f}s. Resumed production elapsed: {raw['elapsed_s']:.2f}s (not total initial + migration + replay time). Reconciliation/publication elapsed: {rec['elapsed_s']:.2f}s; process peak {rec.get('runtime_memory',{})}. Full native time is substantial; bounded memory is not a real-time ingestion claim.\n")
    rows.append('\nReferences checked: [FIRMS archive](https://firms.modaps.eosdis.nasa.gov/download/) supports JSON and reports approximately5-month SP lag, whereas [README](https://firms.modaps.eosdis.nasa.gov/download/Readme.txt) says3months. Neither generic lag proves completeness; actual member boundaries above control this product. [MODIS fields](https://firms.modaps.eosdis.nasa.gov/content/descriptions/FIRMS_MODIS_Firehotspots.html) and [VIIRS fields](https://firms.modaps.eosdis.nasa.gov/content/descriptions/FIRMS_VIIRS_Firehotspots.html) define UTC, nominal centers, confidence and FRP. NASA aggregate attributes URL returned403. [NOAA revised cessation](https://www.nesdis.noaa.gov/news/update-3-cessation-of-suomi-national-polar-orbiting-partnership-s-npp-data-users-november-02-2026-1540-utc-and-decommissioning-issued-october-30-2026-1400-utc) specifies2Nov2026 15:40UTC. Source statements, actual reproduced intake and unresolved lineage are distinguished.\n')
    write('CANADA_ARCHIVE_FORENSICS.md','\n'.join(rows))
    rows=['# Canada native recount — independently accepted\n',f"Candidate `{raw['candidate_id']}`. Positive-native candidate only; original Portugal release and G4 unchanged.\n",'|Source / product class|Accepted native records|10 km occupied source-cell UTC days|\n|---|---:|---:|']
    rows += [f"|{key.replace('|',' / ')}|{v['records']:,}|{v['cell_days']:,}|" for key,v in rec['total_by_source_product'].items()]
    rows += [f"\nEvery accepted raw identity + independent5km bin: **{rec['raw_identity_and_projected_5km_keys']['keys']:,} keys**, SHA-256 `{rec['raw_identity_and_projected_5km_keys']['sha256']}`. Every source/product/month/cell/date/DN multiplicity: {rec['independent_daily_multiset']['keys']:,} keys, SHA-256 `{rec['independent_daily_multiset']['sha256']}`. Zero mismatches. The raw oracle imports no production module: independent pretty-JSON reader, UTC/source validation and ellipsoidal EPSG9820 equations; PROJ production projection. Both independently read original ZIPs and deduplicate into separate disk indexes. Whole member row/duplicate/hash accounting must agree before publishing.\n",'\n|Counting scale|Source / class|Occupied cell-days|\n|---|---|---:|']
    rows += [f'|{scale}m|{s} / {pc}|{n:,}|' for scale,items in rec['sensitivity_cell_days'].items() for s,pc,n in items]
    rows += ['\n5/10/20km sensitivity is a change of spatial estimand, not evidence of calibrated sensors. No scale was selected for improved agreement. Pilot fixtures independently apply PROJ inverse cell centers to oracle daily keys in two frozen tracts across2010/2022/2023; client tests use separate inverse math. D/N K uses union; same day/cell reported in D and N counts once in All.\n','**Limits:** exact software reconciliation does not certify NASA source completeness, upstream production lineage, cloud-free observation, real incident truth, independent human review or harmonization. Original signed G4 release gates remain unmet. Full native archive inventory is not holdout performance.\n']
    independent=read('CANADA_NATIVE_ORACLE_FINAL.json')
    rows.append(f"\nAdditional genuinely independent aggregation acceptance: **{independent['public_chunks_verified']} public chunks**, {independent['accepted_records']:,} accepted records and {independent['daily_multiset']['keys']:,} source/product/cell/date/DN multiplicities checked using Python counters + sets and mathematical floor, without the production SQL GROUP BY or binning helper. All three scale unions match. Elapsed {independent['elapsed_s']:.2f}s; largest simultaneous per-month key count {independent['maximum_per_month_keys']:,}, guard {independent['per_month_key_guard']:,}. This supplements the earlier SQL consistency check and raw independent parser/projection. The client requires the hash-bound independent acceptance artifact before showing Canada totals.\n")
    write('CANADA_NATIVE_RECOUNT.md','\n'.join(rows))
    year=collections.defaultdict(lambda:collections.Counter())
    for c in coverage['coverage']:year[c['month'][:4]][c['source']+' / '+c['pc']]+=c['records']
    rows=['# Canada source status\n','ACQUIRED: both hash-verified original JSON ZIPs. STAGED: disk-backed native partitions/index. RECOUNT VERIFIED: every accepted key and daily multiplicity. NATIVE CANDIDATE AVAILABLE: source/product-separated browser history. QUALIFIED COMPLETE MONTHS: not established. RELEASED HARMONIZED PRODUCTS: none.\n','2010–2011 VIIRS: SOURCE_NOT_YET_IN_ERA. January2012: partial FIRMS era from20Jan. November2026: partial S-NPP era ending2Nov15:40UTC. Acquired member spans and positive month presence are distinct from verified valid observation support and expected/received delivery. Unrepresented product months, missing products and no reported rows are separate labels; none becomes fire-free days.\n','|UTC year|Reported rows by native source / processing class|\n|---|---|']+[f'|{y}|{dict(v)}|' for y,v in sorted(year.items())]
    rows.append('\nFull exact monthly/source/day/DN inventory and artifact SHA-256 are in `CANADA_SOURCE_COVERAGE.json`; literal monthly row-version codes/ranges in `CANADA_VERSION_LINEAGE.json`. No inferential seasonal score or common observation interval. C0/C1/C2 pass. C3 is eligible for **native positive evidence only**, not complete observation calendar. C4 blocked by unqualified L2/QA support; C5 not run; G4 WITHHELD.\n')
    write('CANADA_SOURCE_STATUS.md','\n'.join(rows))

if __name__=='__main__':run()
